#!/bin/bash
# Restore backend/.env from embedded base64 at every session start
set -euo pipefail

if [ "${CLAUDE_CODE_REMOTE:-}" != "true" ]; then
  exit 0
fi

ENV_FILE="${CLAUDE_PROJECT_DIR:-/home/user/3-Lakes-Logistics}/backend/.env"

echo "" | base64 -d > "$ENV_FILE"

echo "backend/.env restored"
